    var out = $('.cd-t', el) || el, left = o.seconds || 0, endAt = o.until ? +o.until : null, id = null, al = null, warnAt = o.warnAt == null ? 120 : o.warnAt;
    if (endAt) left = Math.max(0, (endAt - Date.now()) / 1000);
    function render() { out.textContent = fmt(left); el.classList.toggle('cd-warn', left > 0 && left <= warnAt && !!id); if (o.onTick) o.onTick(left, endAt ? new Date(endAt) : new Date(Date.now() + left * 1000)); }
    function tick() { left = Math.max(0, (endAt - Date.now()) / 1000); render(); if (left <= 0) finish(); }
    function finish() { clearInterval(id); id = null; el.setAttribute('aria-pressed', 'false'); el.classList.remove('cd-warn'); el.classList.add('cd-done'); if (o.alarm !== false) al = alarm(); if (o.onDone) o.onDone(); }
