    function stop() { if (id) { clearInterval(id); id = null; } if (!o.until) endAt = null; el.setAttribute('aria-pressed', 'false'); render(); }
    function dismiss() { if (al) { al.stop(); al = null; } el.classList.remove('cd-done'); }
