    var clockEl = $('.cd-break-clock', el), backAt = $('.cd-back-at', el), minsOut = $('.cd-break-mins', el);
    var o = { el: clockEl, warnAt: (+el.getAttribute('data-warn') || 2) * 60,
      onTick: function (left, end) { if (backAt) backAt.textContent = clock(end); if (minsOut) minsOut.textContent = Math.max(1, Math.ceil(left / 60)); el.classList.toggle('cd-warn', clockEl.classList.contains('cd-warn')); },
      onDone: function () { el.classList.remove('cd-warn'); el.classList.add('cd-done'); } };
    var until = el.getAttribute('data-until');
    if (until) { var p = until.split(':'), d = new Date(); d.setHours(+p[0], +p[1], 0, 0); if (d < Date.now()) d.setDate(d.getDate() + 1); o.until = d; }
    else o.seconds = (+el.getAttribute('data-minutes') || 10) * 60;
    var t = timer(o);
    $$('[data-d]', el).forEach(function (b) { b.onclick = function () { el.classList.remove('cd-done'); t.add(+b.getAttribute('data-d')); }; });
    var tm = $('input[type=time]', el); if (tm) tm.onchange = function () { var p = tm.value.split(':'); if (p.length < 2) return; var d = new Date(); d.setHours(+p[0], +p[1], 0, 0); el.classList.remove('cd-done'); t.setUntil(d); t.start(); };
    clockEl.onclick = function () { if (t.done) { t.dismiss(); el.classList.remove('cd-done'); return; } t.toggle(); };
    return t;
