/* ══ CODED deck kit · CodedKit ═══════════════════════════════════════
   The one call a deck makes:

     CodedKit.mount({
       sections:[{n:'Opening',g:'g-mark'}, …],   // one per data-sec value, 4–6 of them
       flows:{ day:{ steps:[…], branches:{…}, stages:{kb:[1,2]} } }   // optional
     });

   It mounts CodedDeck (navigation, progress, menu, staged reveal, echo field)
   and CodedPresenter (bell, timers, break clock), then adds:
     · speaker notes  — data-notes on each slide, N toggles the panel
     · html[data-cur] — the current slide's archetypes, so fixed chrome can react
     · flowcharts     — <div class="big-fc" data-flow="day" data-lit="kb">
     · lit paths      — <div class="cd-leads" data-lights="flowId"> buttons with data-path / data-out
     · spines         — <div class="cd-spine" data-panels="#panelId"> + <template> per step
   ═══════════════════════════════════════════════════════════════════ */
(function (root) {
  var $ = function (q, c) { return (c || document).querySelector(q); };
  var $$ = function (q, c) { return [].slice.call((c || document).querySelectorAll(q)); };
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function mins(sec) { sec = +sec || 0; return sec >= 60 ? Math.round(sec / 60) + ' min' : sec + ' s'; }

  /* ── flowchart ──────────────────────────────────────────────────────
     spec = {
       trigger: 'Lead',                         // optional start oval
       steps:  ['Ask age', ['?','Age fits?'], ['o','Enrolled',true]],
               // string = step (rectangle) · ['?',text] = decision (diamond)
               // ['o',text,win] = end (oval; win=true fills it)
       branches: { 1:['No','Reject · redirect'] },  // keyed by step index: [label, outcome, win]
       stages:  { kb:[0,1], pay:[4,5,'b5'] }        // named highlight sets for data-lit
     }
     Node ids for lighting: 't' trigger, 's0…sN' steps, 'a0…aN' the arrow INTO step N, 'b<k>' branch k. */
  function flowHTML(spec, lit, cls) {
    var steps = spec.steps || [], br = spec.branches || {}, trig = spec.trigger;
    var n = steps.length * 2 - 1 + (trig ? 2 : 0);
    var L = function (id) { return lit ? (lit.indexOf(id) > -1 ? ' lit' : ' dim') : ''; };
    var h = '<div class="s7-fc ' + (cls || '') + '" style="--n:' + n + '">';
    if (trig) h += '<div class="c"><span class="fc-o' + L('t') + '" data-n="t">' + esc(trig) + '</span></div>';
    steps.forEach(function (s, k) {
      var t = Array.isArray(s) ? s : ['r', s];
      if (k || trig) h += '<div class="c"><span class="fc-ar' + L('a' + k) + '" data-n="a' + k + '"></span></div>';
      var id = 's' + k, body;
      if (t[0] === 'o') body = '<span class="fc-o end' + (t[2] ? ' win' : '') + L(id) + '" data-n="' + id + '">' + esc(t[1]) + '</span>';
      else if (t[0] === '?' || t[0] === 'd') body = '<span class="fc-d' + L(id) + '" data-n="' + id + '"><span>' + esc(t[1]) + '</span></span>';
      else body = '<span class="fc-r' + L(id) + '" data-n="' + id + '">' + esc(t[1]) + '</span>';
      h += '<div class="c" style="--i:' + k + '">' + body + '</div>';
    });
    Object.keys(br).forEach(function (k) {
      k = +k; var b = br[k], col = 2 * k + (trig ? 3 : 1);
      h += '<div class="c row2" style="grid-column:' + col + '"><div class="c down' + L('b' + k) + '" data-n="b' + k + '">' +
        '<span class="lbl">' + esc(b[0]) + '</span><span class="vl"></span><span class="fc-o end' + (b[2] ? ' win' : '') + '">' + esc(b[1]) + '</span></div></div>';
    });
    return h + '</div>';
  }
  function expandLit(spec, key) {
    if (!key || key === 'all') return null;
    var named = spec.stages && spec.stages[key];
    var list = named || String(key).split(',');
    var out = [];
    list.forEach(function (x) {
      x = String(x).trim();
      if (/^\d+$/.test(x)) { out.push('s' + x); out.push('a' + x); }   // a step lights with the arrow into it
      else out.push(x);
    });
    return out;
  }
  function renderFlows(flows) {
    $$('[data-flow]').forEach(function (el) {
      var spec = flows[el.getAttribute('data-flow')];
      if (!spec) { console.error('CodedKit: no flow named "' + el.getAttribute('data-flow') + '" in CodedKit.mount({flows})'); return; }
      var key = el.getAttribute('data-lit');
      if (key && key !== 'all' && !(spec.stages && spec.stages[key]) && !/^[tsab]?\d*(,\s*[tsab]?\d+)*$/.test(key))
        console.error('CodedKit: data-lit="' + key + '" is not a stage of flow "' + el.getAttribute('data-flow') + '" (stages: ' + Object.keys(spec.stages || {}).join(', ') + ')');
      var lit = expandLit(spec, el.getAttribute('data-lit'));
      var mini = el.classList.contains('mini');
      el.innerHTML = flowHTML(spec, lit, (mini ? 'mini' : '') + (lit ? ' lit-mode' : ''));
    });
  }

  /* ── lit paths: buttons light a route through a rendered flow ── */
  function wireLights() {
    $$('[data-lights]').forEach(function (group) {
      var target = $(group.getAttribute('data-lights')), out = group.getAttribute('data-outlet') ? $(group.getAttribute('data-outlet')) : null;
      if (!target) return;
      root.CodedDeck.pickGroup(group, function (i, b) {
        var fc = target.querySelector('.s7-fc') || target;
        var path = (b.getAttribute('data-path') || '').split(',').map(function (s) { return s.trim(); });
        fc.setAttribute('data-lit', '');
        $$('[data-n]', fc).forEach(function (n) { n.classList.toggle('lit', path.indexOf(n.getAttribute('data-n')) > -1); });
        if (out && b.hasAttribute('data-out')) out.innerHTML = b.getAttribute('data-out');
      });
    });
  }

  /* ── spines: a step list that swaps a detail panel and grows the rail ── */
  function wireSpines() {
    $$('.cd-spine[data-panels]').forEach(function (sp) {
      var panel = $(sp.getAttribute('data-panels')), fill = $('.cd-spine-fill', sp), tpls = $$('template', sp);
      var n = $$('button', sp).length;
      root.CodedDeck.pickGroup(sp, function (i) {
        if (panel && tpls[i]) panel.innerHTML = tpls[i].innerHTML;
        if (fill) fill.style.height = (n > 1 ? i / (n - 1) * 100 : 0) + '%';
      });
      var first = $('button[aria-pressed=true]', sp) || $('button', sp);
      if (first) first.click();
    });
  }

  /* ── speaker notes ── */
  function notes(deckEl, slides) {
    var panel = $('#notes');
    if (!panel) {
      panel = document.createElement('div'); panel.id = 'notes'; panel.setAttribute('aria-live', 'polite');
      panel.innerHTML = '<span class="cd-k">Speaker notes · N to hide</span><p id="notesBody"></p>';
      document.body.appendChild(panel);
    }
    var body = $('p', panel), cur = slides[0];
    function render() {
      if (!cur) return;
      var t = cur.getAttribute('data-notes') || 'No note for this slide.';
      var d = cur.getAttribute('data-dur');
      body.textContent = (d ? '[' + mins(d) + '] ' : '') + t;
    }
    deckEl.addEventListener('cd:slide', function (e) { cur = e.detail.slide; render(); });
    addEventListener('keydown', function (e) {
      if (e.key !== 'n' && e.key !== 'N') return;
      var tag = (e.target.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea' || e.metaKey || e.ctrlKey) return;
      panel.classList.toggle('cd-on'); render();
    });
    render();
  }

  function archetypes(sl) {
    return [].slice.call(sl.classList).filter(function (c) { return c.indexOf('cd-slide--') === 0; })
      .map(function (c) { return c.slice(10); }).join(' ');
  }

  function mount(opt) {
    opt = opt || {};
    var deckEl = $(opt.deck || '#deck');
    if (!deckEl) { console.error('CodedKit: no #deck'); return null; }
    var slides = $$('.cd-slide', deckEl);
    deckEl.addEventListener('cd:slide', function (e) {
      document.documentElement.setAttribute('data-cur', archetypes(e.detail.slide));
    });
    if (opt.flows) renderFlows(opt.flows);
    notes(deckEl, slides);
    var deck = root.CodedDeck.mount({
      deck: deckEl, sections: opt.sections || [{ n: 'Deck', g: 'g-mark' }],
      count: '#count', prog: '#prog', menu: '#menu', menuGrid: '#menuGrid', echo: '#echo'
    });
    if (root.CodedPresenter) root.CodedPresenter.mount(opt.presenter || {});
    wireLights(); wireSpines();
    return deck;
  }

  root.CodedKit = { mount: mount, flowHTML: flowHTML, renderFlows: renderFlows, version: '0.1' };
})(window);
